</span></span><span class=\"s22\"><span class=\"bumpedFont15\">މިހާތަނަށް</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ބެލިބެލުމުން</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">އެ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ޤައުމުގައި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ދިރިއުޅޭ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ދިވެހިންގެ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ޙާލު</span></span><span class=\"s22\"><span class=\"bumpedFont15\">ރަނގަޅުކަމަށް</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ވަނީ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">މައުލޫމާތު</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ލިބިފައެވެ</span></span><span class=\"s22\"><span class=\"bumpedFont15\">. </span></span><span class=\"s22\"><span class=\"bumpedFont15\">އަދި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">މިޔަންމާގައި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">އެއްވެސް</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ދިވެހި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ރައްޔިތަކު</span></span><span class=\"s22\"><span class=\"bumpedFont15\">މިވަގުތު</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ހ</span></span><span class=\"s22\"><span class=\"bumpedFont15\">ުރިތޯބެލުމަށް ޑިޕްލޮމެޓިކް ޗެނަލްތައް މެދުވެރިކޮށް މިދަނީ މަސައްކަތް ކުރަމުންނެވެ.</span></span></p>\r\n<p class=\"s19\" dir=\"rtl\"><span class=\"s24\"><span class=\"bumpedFont15\"> </span></span></p>\r\n<p class=\"s19\" dir=\"rtl\"><span class=\"s22\"><span class=\"bumpedFont15\">މި ކާރިސާއާ ގުޅިގެން ތައިލެންޑާއި މިޔަންމާއިން ވަނީ ކުއްލި ހާލަތު އިއުލާނު ކޮށްފައެވެ. ވުމާއެކު، އެ ދެ ޤައުމުގެ ކަމާބެހޭ އިދާރާތަކުން މިކަމާ ގުޅިގެން އަންގާ އެންގުންތަކަށްސަމާލުވެ އެއާ އެއްގޮތަށް ޢަމަލު ކުރުމަށް، އެ ދެ ޤައުމުގައި ތިބި ދިވެހި ރައްޔިތުންނަށް މި މިނިސްޓްރީން އިލްތިމާސްކުރަމެވެ.</span></span><span class=\"s23\"><span class=\"bumpedFont15\">  </span></span><span class=\"s22\"><span class=\"bumpedFont15\">މި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ކާރިސާއާ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ގުޅިގެން، </span></span><span class=\"s22\"><span class=\"bumpedFont15\">ތައިލެންޑްގައި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ތިބި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ދިވެހި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ރައްޔިތުންގެ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ތެރެއިން</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">އެއްވެސް</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ބޭފުޅަކު</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">އެހީތެރިކަމެއް</span></span><span class=\"s22\"><span class=\"bumpedFont15\">ބޭނުންފުޅުވާނަމަ،</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ނުވަތަ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">އިތުރު</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">މަޢުލޫމާތު</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ސާފުކުރައްވަން</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ބޭނުންފުޅުވާނަމަ، </span></span><span class=\"s22\"><span class=\"bumpedFont15\">ތައިލެންޑްގައި</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ހުންނަ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ދިވެހިރާއްޖޭގެ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">އެ</span></span><span class=\"s22\"><span class=\"bumpedFont15\">މްބަސީގެ ހޮޓްލައިން ނަންބަރަށް ނުވަތަ މިނިސްޓްރީގެ ހޮޓްލައިން ނަންބަރަށް ގުޅުއްވުމަށް ދަންނަވަމެވެ. އަދި މިޔަންމާގައި މިވަގުތު އެއްވެސް ދިވެހި ރައްޔިތެއްވާނަމަ، އަދި އެ ބޭފުޅަކަށް އެއްވެސް އެހީތެރިކަމެއް ބޭނުންފުޅުވާނަމަ، ތިރީގައިވާ ނަންބަރުތަކަށް ގުޅުއްވުމަށް ދަންނަވަމެވެ.</span></span></p>\r\n<p class=\"s19\" dir=\"rtl\"><span class=\"s25\"><span class=\"bumpedFont15\"><br /></span></span><span class=\"s22\"><span class=\"bumpedFont15\">އެމްބަސީ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ހޮޓްލައިން</span></span><span class=\"s22\"><span class=\"bumpedFont15\"> ނަންބަރު: 611766502 66+</span></span></p>\r\n<p class=\"s19\" dir=\"rtl\"><span class=\"s22\"><span class=\"bumpedFont15\">މިނިސް</span></span><span class=\"s22\"><span class=\"bumpedFont15\">ޓްރީ</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ހ</span></span><span class=\"s22\"><span class=\"bumpedFont15\">ޮޓްލައިން</span></span> <span class=\"s22\"><span class=\"bumpedFont15\">ނ</span></span><span class=\"s22\"><span class=\"bumpedFont15\">ަންބަ</span></span><span class=\"s22\"><span class=\"bumpedFont15\">ރު:</span></span><span class=\"s22\"><span class=\"bumpedFont15\">96079834</span></span><span class=\"s22\"><span class=\"bumpedFont15\">00</span></span><span class=\"s22\"><span class=\"bumpedFont15\">+</span></span></p>', 1, 28, '2025-03-28 11:02:44', 848, '', '2025-03-28 11:17:59', 848, NULL, NULL, '2025-03-28 11:02:44', NULL, '{\"image_intro\":\"images\\/nus%20bayan%201080550.jpg#joomlaImage:\\/\\/local-images\\/nus bayan 1080550.jpg?width=2852&height=1452\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/nus%20bayan%201080550.jpg#joomlaImage:\\/\\/local-images\\/nus bayan 1080550.jpg?width=2852&height=1452\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 4, 446, '', '', 1, 1215, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, '*', ''),
(4548, 5275, 'Minister Dr. Abdulla Khaleel sends Independence Day greetings to the Republic of Senegal', 'minister-dr-abdulla-khaleel-sends-independence-day-greetings-to-the-republic-of-senegal', '<p>Ref: 2025/PR/77</p>\r\n', '\r\n<p>Minister of Foreign Affairs, Dr. Abdulla Khaleel has sent a message of felicitations to the Minister of African Integration and Foreign Affairs of the Republic of Senegal, Yassine Fall on the joyous occasion of the Independence Day of Senegal. </p>\r\n<p>Minister’s message reads as follows: <br /> <br />“The Government and the people of Maldives join me in extending warm greetings to Your Excellency, the Government and the people of the Republic of Senegal on the joyous occasion of Senegal’s Independence Day.</p>\r\n<p>Let me also convey my best wishes for Your Excellency’s good health and well-being, as well as for progress and prosperity for the people of Senegal.</p>\r\n<p>Please accept, Excellency, the assurances of my highest consideration.”</p>\r\n<p>ENDS</p>', 1, 18, '2025-04-04 05:58:59', 848, '', '2025-04-04 05:58:59', 848, NULL, NULL, '2025-04-04 05:58:59', NULL, '{\"image_intro\":\"images\\/press%20release%201080x550.jpg#joomlaImage:\\/\\/local-images\\/press release 1080x550.jpg?width=1280&height=652\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/press%20release%201080x550.jpg#joomlaImage:\\/\\/local-images\\/press release 1080x550.jpg?width=1280&height=652\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 1, 537, '', '', 1, 1099, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, 'en-GB', ''),
(4549, 5276, 'ސެނެގާލްގެ މިނިވަން ދުވަހުގެ މުނާސަބަތުގައި ޚާރިޖީ ވަޒީރު ޑރ. ޢަބްދުﷲ ޚަލީލް އެ ޤައުމުގެ ޚާރިޖީ ވަޒީރަށް ތަހުނިޔާ ފޮނުއްވައިފި', 'senegalge-minivan-duvahuge-munasabatugai-khariji-vaziru-dr-abduallh-khalil-e-qaumuge-khariji-vaziras-tahuniya-fonuvaifi', '<p dir=\"rtl\">Ref: 2025/PR/77</p>\r\n', '\r\n<p dir=\"rtl\">ރިޕަބްލިކް އޮފް ސެނެގާލްގެ މިނިވަންދުވަހުގެ މުނާސަބަތުގައި އެ ޤައުމުގެ ޚާރިޖީ ވަޒީރު ޔަސިން ފޯލްއަށް، ޚާރިޖީ ވަޒީރު ޑރ. ޢަބްދުﷲ ޚަލީލް ތަހުނިޔާގެ މެސެޖެއް ފޮނުއްވައިފިއެވެ.</p>\r\n<p dir=\"rtl\">މިނިސްޓަރުގެ މެސެޖު ތިރީގައި އެވަނީއެވެ.</p>\r\n<p dir=\"rtl\">\"ރިޕަބްލިކް އޮފް ސެނެގާލްގެ މިނިވަން ދުވަހުގެ އުފާވެރި މުނާސަބަތުގައި، ދިވެހި ސަރުކާރާއި ދިވެހި ރައްޔިތުންގެ ނަމުގައި ކަމަނާއަށާއި ސެނެގާލްގެ ރައްޔިތުންނަށް ތަހުނިޔާއާއި ހެޔޮއެދުންތައް އަރިސްކުރަމެވެ.</p>\r\n<p dir=\"rtl\">މި ފުރުޞަތުގައި، ކަމަނާއަށް ދުޅަހެޔޮ ޞިއްޙަތާއި ސެނެގާލްގެ ރައްޔިތުންނަށް އިތުރު ކުރިއެރުމާއި އުފާފާގަތިކަން ލިބުމަށް އަޅުގަނޑު އެދެމެވެ.</p>\r\n<p dir=\"rtl\">އަޅުގަނޑު ކަމަނާއަށް ކުރާ މަތިވެރި ގަދަރު އާކޮށް، އެކަން ޔަޤީންކޮށް އެރުވުމަށް މި ފުރުޞަތުގެ ބޭނުންކުރީމެވެ.\"</p>\r\n<p dir=\"rtl\">ނިމުނީ</p>', 1, 28, '2025-04-04 06:00:44', 848, '', '2025-04-04 06:00:44', 848, NULL, NULL, '2025-04-04 06:00:44', NULL, '{\"image_intro\":\"images\\/nus%20bayan%201080550.jpg#joomlaImage:\\/\\/local-images\\/nus bayan 1080550.jpg?width=2852&height=1452\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/nus%20bayan%201080550.jpg#joomlaImage:\\/\\/local-images\\/nus bayan 1080550.jpg?width=2852&height=1452\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 1, 445, '', '', 1, 548, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, 'dv-MV', ''),
(4550, 5277, 'Maldives condemns Israeli airstrikes on Gaza schools and the destruction of a medical warehouse belonging to the Saudi Centre for Culture and Heritage', 'maldives-condemns-israeli-airstrikes-on-gaza-schools-and-the-destruction-of-a-medical-warehouse-belonging-to-the-saudi-centre-for-culture-and-heritage', '<p>Ref: 2025/Statement/09</p>\r\n', '\r\n<p>The Government of the Republic of Maldives condemns in the strongest of terms the Israeli forces’ bombing of Dar Al-Arqam School in Gaza, which was sheltering internally displaced persons, causing the deaths of dozens of civilians, including women and children and injuring many more.</p>\r\n<p>The Government of Maldives also condemns the Israeli airstrike that targeted a medical warehouse operated by the Saudi Center for Culture and Heritage in the Morag area of Rafah, destroying essential medical supplies intended to aid those injured in Gaza, in flagrant violations of international law and international humanitarian law.</p>\r\n<p>The Maldives calls on the international community to take urgent and decisive action to end the Israeli violence against the Palestinian people and to ensure humanitarian access to the Gaza Strip. </p>\r\n<p>The Maldives reiterates its firm support for the legitimate rights of the Palestinian people to self-determination and the establishment of an independent and sovereign State of Palestine, based on the pre-1967 borders, with East Jerusalem as its capital.</p>\r\n<p>ENDS</p>', 1, 19, '2025-04-05 11:31:46', 848, '', '2025-04-05 11:31:46', 848, NULL, NULL, '2025-04-05 11:31:46', NULL, '{\"image_intro\":\"images\\/statement%20by%20the%20government%20of%20maldives%201080x550.jpg#joomlaImage:\\/\\/local-images\\/statement by the government of maldives 1080x550.jpg?width=1280&height=651\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/statement%20by%20the%20government%20of%20maldives%201080x550.jpg#joomlaImage:\\/\\/local-images\\/statement by the government of maldives 1080x550.jpg?width=1280&height=651\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 1, 60, '', '', 1, 4999, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, 'en-GB', ''),
(4551, 5278, 'އިސްރާއީލުން ޣައްޒާގެ ސްކޫލަކަށް ދިން ހަމަލާއާއި ބޭސްފަރުވާއަށް ބެނުންވާ ސާމާނު ރައްކާކުރާ ގުދަނަކަށް ދިން ހަމަލާތައް ކުށްވެރިކޮށް ދިވެހި ސަރުކާރުން ނެރޭ ނޫސްބަޔާން', 'israilun-gazage-skulakas-din-hamalaai-besfaruvaas-benunva-samanu-rakakura-gudanakas-din-hamalata-kusverikos-divehi-sarukarun-nere-nusbayan', '<p dir=\"rtl\">Ref: 2025/Statement/09</p>\r\n', '\r\n<p dir=\"rtl\">ޣައްޒާގެ ދާރުލް އަރްޤަމް ސްކޫލަށް އިސްރާއީލު ސިފައިން ދިން ބޮމުގެ ހަމަލާ ދިވެހި ސަރުކާރުން އެންމެ ހަރުކަށި އިބާރާތުން ކުށްވެރިކުރަމެވެ. މި ހަމަލާގައި ކުށެއްނެތް އަންހެނުންނާއި ކުޑަކުދިން މަރުވެ އެތަކެއް ބަޔަކުވަނީ ޒަޚަމްވެފައެވެ.<br /> <br />މީގެ އިތުރުން، ސަޢޫދީ ސެންޓަރ ފޯ ކަލްޗަރ އެންޑް ހެރިޓޭޖުން ޣައްޒާގައި ހިންގާ ބޭސްފަރުވާއަށް ބޭނުންވާ ސާމާނު ރައްކާކުރާ ގުދަނަކަށް އިސްރާއީލުން ދިން ހަމަލާވެސް ދިވެހި ސަރުކާރުން ކުށްވެރިކުރަމެވެ. މިދަފަ ހަމަލާތަކަކީ ބައިނަލްއަޤްވާމީ ޤަނޫނާއި ބައިނަލްއަޤްވާމީ އިންސާނިއްޔަތުކަމާބެހޭ ޤާނޫނާ މުޅިން ޚިލާފު އަމަލުތަކެއްކަން ފާހަގަކުރަމެވެ.</p>\r\n<p dir=\"rtl\">އިސްރާއީލުން ހިންގާ މިފަދަ އަނިޔާވެރި ޢަމަލުތައް ވަގުތުން ހުއްޓުވައި، މި ޢަމަލުތަކަށް އިސްރާއީލު ޖަވާބުދާރީކުރުވައި، ޣައްޒާގެ ރައްޔިތުންގެ އަސާސީ ބޭނުންތައް ފުށްދުމަށް ބޭނުންވާ އެހީތެރިކަން ފޯރުކޮށްދިނުމަށް ބައިނަލްއަޤްވާމީ މުޖުތަމަޢަށް ދިވެހިރާއްޖެއިން ގޮވާލާ ގޮވާލުން ތަކުރާރުކުރަމެވެ.</p>\r\n<p dir=\"rtl\">ދިވެހިރާއްޖެއިން ފަލަސްޠީނުގެ ރައްޔިތުންނަށް ކުރާ ތާޢީދު ތަކުރާރުކޮށް، މި މައްސަލައަށް ދެމެހެއްޓެނިވި އަދި ޢަދުލުވެރި ޙައްލެއް ހޯދޭނީ 1967 ވަނަ އަހަރުގެ ކުރިން ކަނޑައެޅިފައި އޮތް އިންތަކުގެ މައްޗަށް ބިނާކޮށް، އިރުމަތީ ޤުދުސްއަކީ ފަލަސްޠީނުގެ ވެރިކަންކުރާ ރަށްކަމުގައި ކަނޑައަޅައި، ފަލަސްޠީނުގެ މިނިވަން ދައުލަތެއް ޤާއިމުކުރެވިގެންކަމުގައި ދިވެހިރާއްޖެއިން ދެކެމެވެ.</p>', 1, 29, '2025-04-05 11:33:51', 848, '', '2025-04-05 11:33:51', 848, NULL, NULL, '2025-04-05 11:33:51', NULL, '{\"image_intro\":\"images\\/nus%20bayan%201080550.jpg#joomlaImage:\\/\\/local-images\\/nus bayan 1080550.jpg?width=2852&height=1452\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/nus%20bayan%201080550.jpg#joomlaImage:\\/\\/local-images\\/nus bayan 1080550.jpg?width=2852&height=1452\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 1, 17, '', '', 1, 2757, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, 'dv-MV', ''),
(4552, 5279, 'މިނިސްޓަރ އޮފް ފޮރިން އެފެއާޒްގެ އަރިހަށް ސަޢޫދީ ޢަރަބިއްޔާގެ ސަފީރު ވަދާޢީ ޒިޔާރަތެއް ކުރައްވައިފި', 'ministar-of-forin-efeazge-arihas-sa-udi-arabiyage-safiru-vada-i-ziyarate-kuravaifi', '<p dir=\"rtl\">Ref: 2025/PR/78</p>\r\n', '\r\n<p dir=\"rtl\">ސަޢޫދީ ޢަރަބިއްޔާގެ ސަރުކާރުން ދިވެހިރާއްޖެއަށް ކަނޑައަޅުއްވާފައި ހުންނަވާ ސަފީރު، މަތުރެކް ބިން ޢަބްދުﷲ އަލްޢަޖާލީން އަލްދޮސަރީ، މިނިސްޓަރ އޮފް ފޮރިން އެފެއާޒް ޑރ. ޢަބްދުﷲ ޚަލީލްގެ އަރިހަށް މިއަދު ހެނދުނު ވަދާޢީ ޒިޔާރަތެއް ކުރައްވައިފިއެވެ. </p>\r\n<p dir=\"rtl\">ޚާރިޖީ ވުޒާރާގައި މިއަދު ކުރިއަށްދިޔަ މިބައްދަލުވުމުގައި މިނިސްޓަރ ޑރ. ޚަލީލްވަނީ، ސަޢޫދީ ސަފީރު ދިވެހިރާއްޖެއާއި ސަޢޫދީ ޢަރަބިއްޔާއާ ދެ ޤައުމުގެ ދެމެދު އޮތް ގާތް ގުޅުން އިތުރަށް ބަދަހިކޮށް ކުރިއެރުވުމަށްޓަކައި ކޮށްދެއްވާފައިވާ މުހިންމު މަސައްކަތްތައް ފާހަގަކުރައްވައި، އެމަނިކުފާނު ކުރެއްވި މަސައްކަތަށް އިޚްލާޞްތެރިކަމާއެކު ޝުކުރު އަދާކުރެއްވިއެވެ. </p>\r\n<p dir=\"rtl\">ސަޢޫދީ ޢަރަބިއްޔާ ސަފީރުގެ ވާހަކަފުޅުގައި، އެމަނިކުފާނުގެ ދައުރުގައި ދިވެހި ސަރުކާރުން އެމަނިކުފާނަށް ދެއްވި އެއްބާރުލުމާއި ބެހެއްޓެވި ގާތްކަމަށްޓަކައި ޝުކުރު އަދާކުރައްވާފައިވެއެވެ. އަދި ކުރިއަށް އޮތްތަނުގައި ދެ ޤައުމުގެ ގުޅުން އިތުރަށް ބަދަހިވެގެންދާނެކަމަށް އުއްމީދުކުރައްވާކަމަށްވެސް ވިދާޅުވިއެވެ. </p>\r\n<p dir=\"rtl\">މި ބައްދަލުވުން ނިންމަވާލައްވަމުން، މިނިސްޓަރ ޑރ. ޚަލީލްވަނީ، ސަޢޫދީ ޢަރަބިއްޔާގެ ސަފީރު އެމަނިކުފާނުގެ ދައުރުގައި ބެހެއްޓެވި ގާތް ރަޙްމަތްތެރިކަން ފާހަގަކުރައްވާފައެވެ. އަދި ސަފީރަށް ކުރިއެރުމާއި ކާމިޔާބީ އަށް އެދިވަޑައިގެން، ސަޢޫދީ ސަރުކާރުން ރާއްޖެއަށް ދެން ކަނޑައަޅުއްވާ އައު ސަފީރަށްވެސް ސަރުކާރުގެ ފުރިހަމަ އެއްބާރުލުން ދެއްވާނެކަމުގެ ޔަގީންކަން ދެއްވާފައިވެއެވެ. </p>\r\n<p dir=\"rtl\">ނިމުނީ</p>', 1, 2, '2025-04-06 11:33:12', 848, '', '2025-04-06 11:33:12', 848, NULL, NULL, '2025-04-06 11:33:12', NULL, '{\"image_intro\":\"images\\/nus%20bayan%201080550.jpg#joomlaImage:\\/\\/local-images\\/nus bayan 1080550.jpg?width=2852&height=1452\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/nus%20bayan%201080550.jpg#joomlaImage:\\/\\/local-images\\/nus bayan 1080550.jpg?width=2852&height=1452\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 1, 2, '', '', 1, 629, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, 'dv-MV', ''),
(4553, 5280, 'Ambassador of Saudi Arabia pays a farewell call on the Minister of Foreign Affairs', 'ambassador-of-saudi-arabia-pays-a-farewell-call-on-the-minister-of-foreign-affairs-2025-pr-78', '<p>Ref: 2025/PR/78</p>\r\n', '\r\n<p>The Ambassador of Saudi Arabia to the Maldives, Matrek Al-Ajalin Aldosari, paid a farewell call on the Minister of Foreign Affairs Dr. Abdulla Khaleel this morning.</p>\r\n<p>During the meeting held at the Ministry of Foreign Affairs, Minister Khaleel conveyed the Government’s deep appreciation to Ambassador for his invaluable contributions to strengthening the brotherly relations between the Maldives and the Kingdom of Saudi Arabia. The Minister also highlighted the Ambassador’s efforts in enhancing close cooperation between the two countries across key areas.</p>\r\n<p>Ambassador Aldosari expressed sincere gratitude to the Government and people of the Maldives for the warm hospitality and friendship extended to him during his tenure. He reaffirmed the Kingdom’s commitment to further strengthening the close and brotherly ties between the two countries.</p>\r\n<p>Minister Khaleel also acknowledged the warmth and friendship the Ambassador maintained throughout his tenure, and expressed confidence that the strong ties between the Maldives and Saudi Arabia will continue to flourish under the leadership of his successor. </p>\r\n<p>The Minister extended his best wishes to Ambassador in his future endeavors and assured the Government’s full support and cooperation to the incoming Ambassador.</p>\r\n<p>ENDS</p>', 1, 18, '2025-04-06 11:33:23', 848, '', '2025-04-07 03:07:23', 848, NULL, NULL, '2025-04-06 11:33:23', NULL, '{\"image_intro\":\"images\\/press%20release%201080x550.jpg#joomlaImage:\\/\\/local-images\\/press release 1080x550.jpg?width=1280&height=652\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/press%20release%201080x550.jpg#joomlaImage:\\/\\/local-images\\/press release 1080x550.jpg?width=1280&height=652\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 3, 536, '', '', 1, 1682, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, 'en-GB', ''),
(4554, 5281, '58th Session of the Human Rights Council concludes with the active participation and engagement of the Maldives Delegation', '58th-session-of-the-human-rights-council-concludes-with-the-active-participation-and-engagement-of-the-maldives-delegation-2025-pr-79', '<p>Ref: 2025/PR/79</p>\r\n', '\r\n<p>The 58th Session of the United Nations Human Rights Council concluded in Geneva today. During the session, the Council adopted 32 resolutions and appointed three Special Procedures Mandate Holders.</p>\r\n<p>Minister of Foreign Affairs Dr Abdulla Khaleel, participated in the High-Level Segment of the Session, delivering the Maldives national statement on 24 February 2025. In his statement, he highlighted the progress made by the Government of Maldives in the promotion and protection of human rights. Minister Khaleel also participated and delivered remarks at two High-level panel discussions and conducted bilateral meetings with several counterparts. Notably, he delivered the keynote address at the High-level side event organised by the Permanent Mission of Maldives in Geneva, in collaboration with other members of the Core Group on the Right to a Healthy Environment, entitled ‘Advancing the Universal Human Right to a Clean, Healthy, and Sustainable Environment: Taking Stock and What Next?’</p>\r\n<p>The Maldives delegation delivered national statements on an array of thematic areas and co-sponsored 18 resolutions, aligning with key government priorities. The Maldives also co-sponsored resolutions on Human rights, Democracy and Rule of Law, Neurotechnology and Human Rights, Right of the Palestinian people to self-determination and Renewal of the Mandate for the Special Rapporteur on the Right to Food, among others..</p>\r\n<p>On behalf of the Core Group on the Right to a Healthy Environment, the Maldives as the penholder, presented a resolution on the Human Right to a Clean, Healthy, and Sustainable Environment, with a particular focus on the Ocean and Human Rights. Additionally, the Maldives as part of the Core Group on Women in Diplomacy introduced a resolution on “Women, Diplomacy and Human Rights” during this session. Both resolutions were adopted by consensus, garnering wide cross regional co-sponsorship and support at the time of adoption.</p>\r\n<p>In addition, the Maldives co-sponsored 47 joint statements including those by the Organisation for Islamic Cooperation (OIC) and the Non-Aligned Movement (NAM). Representing the group of Small Island Developing States (SIDS), the Maldives delivered joint statements on food security and the need for enhanced technical and financial assistance for capacity building to empower SIDS participation in the Council’s work. Furthermore, the Maldives reaffirmed its strong commitment to the Palestine cause, by co-sponsoring joint statements focusing on Palestine and voting in favour of four resolutions concerning the Occupied Palestinian Territory.</p>\r\n<p>The Maldives delegation for the 58th Session of the Human Rights Council was led by Ambassador and Permanent Representative of the Maldives to the United Nations Office at Geneva Dr. Salma Rasheed., . The delegation included Counsellor Mr. Adam Hamid, Counsellor Uza. Aminath Shifaya Ibrahim, Second Secretary Ms. Aishath Rayahyn, Third Secretary Ms. Fathin Shoora Haleem, and Attaché Mr. Raaidh Saeedh from the Permanent Mission.</p>\r\n<p>ENDS.</p>', 1, 18, '2025-04-04 03:06:32', 848, '', '2025-04-20 03:35:57', 848, NULL, NULL, '2025-04-04 03:06:32', NULL, '{\"image_intro\":\"images\\/2025\\/123.png#joomlaImage:\\/\\/local-images\\/2025\\/123.png?width=1080&height=555\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/2025\\/123.png#joomlaImage:\\/\\/local-images\\/2025\\/123.png?width=1080&height=555\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 4, 535, '', '', 1, 1418, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, 'en-GB', ''),
(4555, 5283, 'Minister of Foreign Affairs Dr. Abdulla Khaleel arrives in Malta on an Official Visit', 'minister-of-foreign-affairs-dr-abdulla-khaleel-arrives-in-malta-on-an-official-visit-2025-pr-80', '<p>Ref: 2025/PR/80</p>\r\n', '\r\n<p>The Minister of Foreign Affairs of the Republic of Maldives, Dr. Abdulla Khaleel arrived in the Republic of Malta today on an official visit.</p>\r\n<p>During the visit, the Foreign Minister Dr. Khaleel will meet with his counterpart, Deputy Prime Minister and Minister for Foreign Affairs and Tourism of Malta, Ian Borg to enhance bilateral relations between the Maldives and Malta, as well as exchange views on key issues of mutual interest. </p>\r\n<p>The Minister is also scheduled to meet with key cabinet ministers in Malta to discuss and explore new opportunities for enhanced cooperation between the two nations. Notably, in areas of shared interest such as environment conservation, sustainable development, the transition to renewable energy, and the enhancement of trade and tourism ties. </p>\r\n<p>Minister is accompanied by Secretary, Dr. Hala Hameed and Senior Under Secretary, Mr. Hassan Hussain Shihaab. </p>\r\n<p>ENDS</p>', 1, 18, '2025-04-07 14:08:31', 848, '', '2025-04-07 14:08:31', 848, NULL, NULL, '2025-04-07 14:08:31', NULL, '{\"image_intro\":\"images\\/press%20release%201080x550.jpg#joomlaImage:\\/\\/local-images\\/press release 1080x550.jpg?width=1280&height=652\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/press%20release%201080x550.jpg#joomlaImage:\\/\\/local-images\\/press release 1080x550.jpg?width=1280&height=652\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 1, 534, '', '', 1, 1822, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 0, '*', '');
މިނިސްޓްރީ ހޮޓްލައިން ނަންބަރު:9607983400+<br>އީމެއިލް: consular@foreign.gov.mv</p>\r\n<p dir=\"rtl\"><br>ނިމުނީ</p>', '', 1, 28, '2026-08-27 13:13:08', 851, '', '2026-09-16 08:44:55', 852, 852, '2026-09-16 08:44:55', '2026-08-27 13:13:08', NULL, '{\"image_intro\":\"images\\/2026\\/PRESS%20RELEASE%206.png#joomlaImage:\\/\\/local-images\\/2026\\/PRESS RELEASE 6.png?width=1080&height=550\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/2026\\/PRESS%20RELEASE%206.png#joomlaImage:\\/\\/local-images\\/2026\\/PRESS RELEASE 6.png?width=1080&height=550\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_image_alt_txt\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 2, 31, '', '', 1, 109, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 1, '*', ''),
(5552, 6365, 'Foreign Minister Iruthisham condemns continued Israeli aggression and calls for a strengthened response amongst OIC Member States', 'foreign-minister-iruthisham-condemns-continued-israeli-aggression-and-calls-for-a-strengthened-response-amongst-oic-member-states', '<p>Ref: 2026/PR/200</p>\r\n<p>The Minister of Foreign Affairs, Iruthisham Adam, participated in the Extraordinary Meeting of the Council of Foreign Ministers of the Organization of the Islamic Cooperation (OIC), held today in Jeddah, Saudi Arabia. This marks Minister Iruthisham’s first engagement at the OIC as the Minister of Foreign Affairs of the Republic of the Maldives.</p>\r\n<p>In her remarks, Minister Iruthisham condemned Israel’s continued settlement expansion and annexation of Palestinian land and expressed concerns over the lack of meaningful action to hold Israel accountable for its violations of International Law. She also emphasised the need to respond decisively to the Palestinian cause, reflecting on the shared commitment between Member States to uphold the values of the Muslim Ummah. </p>\r\n<p>The Minister further reiterated that Maldives will remain a steadfast advocate for the Palestinian people in their pursuit of justice, the realization of their legitimate rights, and the establishment of an independent and sovereign State of Palestine based on the pre 1967 borders, with East Jerusalem as its capital. She also called for concrete steps towards implementing the Comprehensive Plan to End the Gaza Conflict, which offers a pathway towards lasting peace. On the sidelines of this meeting, Minister Iruthisham met with the Foreign Ministers of some OIC Member States, underscoring the close relations between Maldives and the OIC.</p>\r\n<p>The Organization of Islamic Cooperation, comprising of 57 Member States, remains a leading advocate for the people of Palestine and their aspiration for statehood. The Maldives has been an active member of the OIC since joining the Organisation in 1976.</p>\r\n<p><br>ENDS</p>', '', 1, 18, '2026-08-27 23:27:42', 851, '', '2026-09-16 08:46:23', 852, 852, '2026-09-16 08:46:23', '2026-08-27 23:27:15', NULL, '{\"image_intro\":\"images\\/2026\\/08\\/WhatsApp%20Image%202026-08-28%20at%2008.22.49.jpg#joomlaImage:\\/\\/local-images\\/2026\\/08\\/WhatsApp Image 2026-08-28 at 08.22.49.jpg?width=1080&height=550\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/2026\\/08\\/WhatsApp%20Image%202026-08-28%20at%2008.22.49.jpg#joomlaImage:\\/\\/local-images\\/2026\\/08\\/WhatsApp Image 2026-08-28 at 08.22.49.jpg?width=1080&height=550\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_image_alt_txt\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 5, 46, '', '', 1, 170, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 1, 'en-GB', ''),
(5553, 6366, 'އިސްރާއީލުން ހުއްޓުމެއްނެތި ހިންގަމުންދާ ޣައިރު ގާނޫނީ އަމަލުތައް ކުށްވެރިކޮށް، އޯ.އައި.ސީ. ގެ މެންބަރު ގައުމުތަކުން ފަލަސްތީނުގެ މައްސަލައަށް ހައްލެއްހޯދުމަށް ކުރާ މަސައްކަތް އިތުރަށް ހަރުދާނަކުރުމަށް ޚާރިޖީ ވަޒީރު އިރުތިޝާމް ގޮވާލައްވައިފި', 'israilun-hutumeneti-hingamunda-gairu-ganuni-amaluta-kusverikos-o-ai-si-ge-menbaru-gaumutakun-falastinuge-masalaas-halehodumas-kura-masakat-ituras-harudanakurumas-khariji-vaziru-irutisam-govalavaifi', '<p dir=\"rtl\">Ref: 2026/PR/200</p>\r\n<p dir=\"rtl\">އޯގަނައިޒޭޝަން އޮފް އިސްލާމިކް ކޯޕަރޭޝަން (އޯ.އައި.ސީ.) އިން ސަޢޫދީ ޢަރަބިއްޔާގެ ޖިއްދާގައި ޚާރިޖީ ވަޒީރުންގެ ފެންވަރުގައި މިއަދު ބޭއްވި އެކްސްޓްރާއޯޑިނަރީ މީޓިންގައި ދިވެހިރާއްޖޭގެ ޚާރިޖީ ވަޒީރު، އިރުތިޝާމް އާދަމް ބައިވެރިވެވަޑައިގެންފިއެވެ. މި ބައްދަލުވުމަކީ ދިވެހިރާއްޖޭގެ ޚާރިޖީ ވަޒީރުގެ ހައިސިއްޔަތުން އޯ.އައި.ސީ.ގެ ބައްދަލުވުމެއްގައި ވަޒީރު އިރުތިޝާމް ބައިވެރިވަޑައިންނެވި ފުރަތަމަ ފަހަރެވެ.</p>\r\n<p dir=\"rtl\">މި ބައްދަލުވުމުގައި އެކަމަނާ ދެއްވި ތަޤުރީރުގައި، އިސްރާއީލުން ފަލަސްތީނުގެ ބިންތަކަކީ އިސްރާއީލީ ދައުލަތުގެ މިލްކެއްކަމުގައި ނިންމައި ފަލަސްތީނުގެ ބިންތައް ހިޞާރުކުރަމުންދާ މައްސަލަ ކުށްވެރިކުރެއްވިއެވެ. އަދި އިސްރާއީލުގެ ޣައިރު ޤާނޫނީ އަމަލުތައް ހުއްޓުވައި އިސްރާއީލުގެ މައްޗަށް ބައިނަލްއަގްވާމީ ގާނޫނުތައް ތަންފީޒުކުރުމަށް އެކަށޭނެ ފިޔަވަޅު އަޅާފައިނުވާތީ އެކަމާ ކަންބޮޑުވުން ފާޅުކުރެއްވިއެވެ. އިސްލާމީ އުއްމަތުގެ ރިވެތި އުސޫލުތަކާ ހަމަތައް ދެމެހެއްޓުމަކީ އޯ.އައި.ސީ. މެމްބަރު ގައުމުތަކުގެ ޒިންމާއެއްކަން ފާހަގަކުރައްވައި، ފަލަސްތީނުގެ މައްސަލައަށް ހައްލެއް ހޯދުމަށް ކުރާ މަސައްކަތް ފުޅާކުރުން މުހިންމުކަމުގައި ވަޒީރު އިރުތިޝާމް ވިދާޅުވިއެވެ. </p>\r\n<p dir=\"rtl\">މީގެ އިތުރުން، ފަލަސްތީނުގެ ރައްޔިތުންނަށް އިންސާފާއި އެމީހުންގެ ހައްޤުތައް ހޯދައިދިނުމަށާއި 1967 ވަނަ އަހަރުގެ ކުރިން ކަނޑައެޅިފައި އޮތް އިންތަކުގެ މައްޗަށް ބިނާކޮށް، އިރުމަތީ ޤުދުސްއަކީ ފަލަސްތީނުގެ ވެރިކަންކުރާ ރަށްކަމުގައި ކަނޑައަޅައި، މިނިވަން އަދި އަމިއްލަ ސިޔާދަތީ ބާރު ހިނގާ ދައުލަތެއްގެ ގޮތުގައި ފަލަސްތީނުގެ ދައުލަތް ގާއިމުކުރުމަށް ދިވެހިރާއްޖެއިން އަބަދުވެސް އެއްބާރުލުން ދޭނެކަމުގެ ޔަޤީންކަން ދެއްވިއެވެ. އަދި ދެމެހެއްޓިނިވި ސުލްހައަކަށް އޮތް މަގެއްގެ ގޮތުގައި \"ކޮމްޕްރިހެންސިވް ޕްލޭން ޓު އެންޑް ދަ ޤާޒާ ކޮންފްލިކްޓް\" ތަންފީޒުކުރުމަށް ވަޒީރު އިރުތިޝާމް ގޮވާލެއްވިއެވެ. އަދި މި ބައްދަލުވުމުގެ ހަވާސާގައި އޯ.އައި.ސީގެ ބައެއް މެންބަރު ޤައުމުތަކުގެ ޚާރިޖީ ވަޒީރުންނާ ބައްދަލުކޮށް، އޯ.އައި.ސީ. އާއި ދިވެހިރާއްޖެ އާއި ދެމެދު އޮތް ގާތް ގުޅުމަށް އަލިއަޅުއްވާލެއްވިއެވެ.</p>\r\n<p dir=\"rtl\"> އޯގަނައިޒޭޝަން އޮފް އިސްލާމިކް ކޯޕަރޭޝަން (އޯ.އައި.ސީ.) އަކީ 57 ގައުމުގެ މައްޗައް އެކުލެވިގެންވާ ފަލަސްތީނުގެ ހައްގުގައި އަބަދުސް ވަކާލާތުކުރަމުން އަންނަ ޖަމުޢިއްޔާއެކެވެ. ދިވެހިރާއްޖެ އަކީ 1976 ގައި މި ޖަމުއިއްޔާގެ މެމްބަރަކަށް ވުމަށްފަހު މި ޖަމުއިއްޔާގައި އިސްކޮށް ހަރަކާތްތެރިވަމުން އަންނަ ގައުމެކެވެ.</p>', '', 1, 28, '2026-08-27 23:28:17', 851, '', '2026-09-16 08:46:51', 852, 852, '2026-09-16 08:46:51', '2026-08-27 23:28:07', NULL, '{\"image_intro\":\"images\\/2026\\/08\\/WhatsApp%20Image%202026-08-28%20at%2008.22.49.jpg#joomlaImage:\\/\\/local-images\\/2026\\/08\\/WhatsApp Image 2026-08-28 at 08.22.49.jpg?width=1080&height=550\",\"image_intro_alt\":\"\",\"float_intro\":\"\",\"image_intro_caption\":\"\",\"image_fulltext\":\"images\\/2026\\/08\\/WhatsApp%20Image%202026-08-28%20at%2008.22.49.jpg#joomlaImage:\\/\\/local-images\\/2026\\/08\\/WhatsApp Image 2026-08-28 at 08.22.49.jpg?width=1080&height=550\",\"image_fulltext_alt\":\"\",\"float_fulltext\":\"\",\"image_fulltext_caption\":\"\"}', '{\"urla\":\"\",\"urlatext\":\"\",\"targeta\":\"\",\"urlb\":\"\",\"urlbtext\":\"\",\"targetb\":\"\",\"urlc\":\"\",\"urlctext\":\"\",\"targetc\":\"\"}', '{\"article_layout\":\"\",\"show_title\":\"\",\"link_titles\":\"\",\"show_tags\":\"\",\"show_intro\":\"\",\"info_block_position\":\"\",\"info_block_show_title\":\"\",\"show_category\":\"\",\"link_category\":\"\",\"show_parent_category\":\"\",\"link_parent_category\":\"\",\"show_associations\":\"\",\"flags\":\"\",\"show_author\":\"\",\"link_author\":\"\",\"show_create_date\":\"\",\"show_modify_date\":\"\",\"show_publish_date\":\"\",\"show_item_navigation\":\"\",\"show_vote\":\"\",\"show_hits\":\"\",\"show_noauth\":\"\",\"urls_position\":\"\",\"alternative_readmore\":\"\",\"article_page_title\":\"\",\"show_publishing_options\":\"\",\"show_article_options\":\"\",\"show_urls_images_backend\":\"\",\"show_urls_images_frontend\":\"\",\"helix_ultimate_image\":\"\",\"helix_ultimate_image_alt_txt\":\"\",\"helix_ultimate_article_format\":\"standard\",\"helix_ultimate_audio\":\"\",\"helix_ultimate_gallery\":\"\",\"helix_ultimate_video\":\"\"}', 2, 30, '', '', 1, 58, '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\"}', 1, 'dv-MV', '');

